import 'package:flutter/material.dart';

/// Tiny built-in translation layer (English / Hindi / Nepali).
///
/// How it works: every user-facing English string in the app is the *key*.
/// `Tr('Home')` (a Text replacement) and `'Home'.tr` look the string up in
/// [_dict] and return the Hindi or Nepali version. If a string has no entry
/// it is shown in English, so nothing ever breaks.
///
/// To add or fix a translation, edit the matching row in [_dict]
/// (order is: English key -> [Hindi, Nepali]).
class I18n {
  /// Set from AppSettings. One of 'English', 'Hindi', 'Nepali'.
  static String lang = 'English';

  static String tr(String s) {
    if (lang == 'English') return s;
    final row = _dict[s];
    if (row == null) return s;
    return lang == 'Hindi' ? row[0] : row[1];
  }
}

extension TrString on String {
  String get tr => I18n.tr(this);
}

/// Drop-in replacement for [Text] that translates its string.
class Tr extends StatelessWidget {
  final String data;
  final TextStyle? style;
  final TextAlign? textAlign;
  final int? maxLines;
  final TextOverflow? overflow;
  final bool? softWrap;

  const Tr(
    this.data, {
    super.key,
    this.style,
    this.textAlign,
    this.maxLines,
    this.overflow,
    this.softWrap,
  });

  @override
  Widget build(BuildContext context) {
    return Text(
      I18n.tr(data),
      style: style,
      textAlign: textAlign,
      maxLines: maxLines,
      overflow: overflow,
      softWrap: softWrap,
    );
  }
}

